            # 2. If current characters match, try to match one more character and stay on '*' 
            return (is_match(p_index + 2, t_index) or 
                    (current_char_matches and is_match(p_index, t_index + 1)))

        # Handling '+' - one or more of the preceding element
        if p_index + 1 < len(pattern) and pattern[p_index + 1] == '+':
            if current_char_matches:
                # Continue matching with '+' by moving to the next character in text
                return is_match(p_index, t_index + 1) or is_match(p_index + 2, t_index + 1)
            return False

        # Match character directly if they are equal
        if current_char_matches:
            return is_match(p_index + 1, t_index + 1)

        # No match found
        return False

